function dump(n, d){
  const o = {id:n.id, name:n.name, type:n.type};
  if (d>0 && 'children' in n) o.children = n.children.map(c=>dump(c,d-1));
  if (n.type==='TEXT') { o.chars = n.characters; o.fontName = n.fontName; o.fontSize = n.fontSize; try{o.fills=n.fills}catch(e){} }
  if ('fills' in n && n.type!=='TEXT') { try{o.fills=JSON.parse(JSON.stringify(n.fills))}catch(e){} }
  if (n.cornerRadius!==undefined) o.cornerRadius = n.cornerRadius;
  if (n.layoutMode) { o.layoutMode=n.layoutMode; o.padding=[n.paddingTop,n.paddingRight,n.paddingBottom,n.paddingLeft]; o.itemSpacing=n.itemSpacing; }
  o.w = Math.round(n.width); o.h = Math.round(n.height);
  return o;
}
