  const inp=F('Input',{dir:'HORIZONTAL',gap:8,pad:[13,16,13,16],calign:'CENTER',align:'SPACE_BETWEEN',fill:C.white});
  inp.strokes=[{type:'SOLID',color:C.line}];inp.strokeWeight=1;inp.cornerRadius=8;
  add(w,inp,'FILL');
  add(inp,await T(placeholder||'',14,'Regular',opts.value?C.ink:C.muted));
  if(opts.chevron){const cd=(await figma.getNodeByIdAsync('13:30')).createInstance();add(inp,cd);cd.resize(18,18);}
