async function coverPhoto(compId,w,h){
  const src=await figma.getNodeByIdAsync(compId);
  const inst=src.createInstance();
  const holder=F('Photo',{dir:'HORIZONTAL'});
  holder.resize(w,h);holder.counterAxisSizingMode='FIXED';holder.primaryAxisSizingMode='FIXED';
  holder.clipsContent=true;holder.cornerRadius=12;holder.fills=[];
  holder.appendChild(inst);
  const sw=inst.width,sh=inst.height;
  const scale=Math.max(w/sw,h/sh);
  inst.resize(sw*scale,sh*scale);
  inst.x=(w-inst.width)/2;inst.y=(h-inst.height)/2;
  return holder;
}

